local b=""
local P="ServerScriptService"
local N="Fireworks"
local C="ModuleScript"
local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function dec(d) d=d:gsub("[^"..B.."=]","")
 return (d:gsub("=*$",""):gsub(".",function(x) local r,f="",(B:find(x)-1)
 for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and "1" or "0") end return r end)
 :gsub("%d%d%d?%d?%d?%d?%d?%d?",function(x) if #x~=8 then return "" end local c=0
 for i=1,8 do c=c+(x:sub(i,i)=="1" and 2^(8-i) or 0) end return string.char(c) end)) end
if game.PlaceId ~= 88774255487951 then return "REFUSED " .. game.PlaceId end
local src = dec(b)
local fn, e = loadstring(src); if not fn then return "SYNTAX ERR " .. tostring(e) end
local node = game
for seg in P:gmatch("[^/]+") do node = node:FindFirstChild(seg); if not node then return "MISSING " .. seg end end
local inst = node:FindFirstChild(N)
if not inst then inst = Instance.new(C); inst.Name = N; inst.Parent = node end
inst.Source = src
return ("%s = %d bytes"):format(N, #src)
